import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
D=json.loads((ROOT/'research/full-proof-integration-20260930/data/full-content.json').read_text())
COMMON=r'''Fix a finite universe $N$, input $x$ and input baseline vector $r$. The mask $x_S$ retains the original coordinates in $S$ and uses this same baseline elsewhere. The model is $v:X\to\mathbb R$, the game is $g(S)=v(x_S)$ and the output baseline is $b=g(\varnothing)$. The paper uses raw dividends $w_A=I_g(A)=\sum_{U\subseteq A}(-1)^{|A|-|U|}g(U)$. Every subset sum includes the empty set, so $w_\varnothing=b$. Centering $g_0=g-b$ changes only the empty dividend. A zero raw output baseline is not assumed.'''
INFO={
'cvpr2023-reconstruction':('Theorem 1: reconstruct every masked output','Expand the dividends and exchange finite double sums. Opposite-sign pairing cancels every output coefficient except that of the retained set.'),
'cvpr2023-uniqueness':('Appendix C: uniqueness of coefficients reconstructing all masks','The empty mask fixes the constant coefficient. At each larger set, subtracting the already fixed proper-subset coefficients uniquely determines its coefficient.'),
'cvpr2023-linearity':('Linearity: pointwise output addition gives dividend addition','Substitute the sum of the two models at every summation subset, then distribute the finite alternating sum.'),
'cvpr2023-dummy':('Dummy: preserve the original proposition and its empty-environment counterexample','The original quantifiers include an empty environment. A one-variable model satisfies the additive premise but has a nonzero singleton dividend, refuting the proposition.'),
'cvpr2023-symmetry':('Symmetry: equal cooperation outputs give equal dividends','Pair subsets with and without the new variable, then use equal cooperation outputs at the same environment in every term.'),
'cvpr2023-anonymity':('Anonymity: variable relabeling preserves dividends','Relabeling bijects the subsets and preserves their cardinalities, signs and corresponding outputs.'),
'cvpr2023-recursive':('Recursive: the interaction difference in the always-present context','Separate the subsets by whether they contain the inserted variable. Their difference is the dividend of the always-present context minus the original dividend.'),
'cvpr2023-interaction-distribution':('Interaction distribution: a pure AND game has a dividend only at its target','Every output vanishes when the target is not contained. At the target there is one surviving term; on strict supersets, remaining variables enable sign cancellation.'),
'cvpr2023-marginal-decomposition':('Theorem 5: dividend decomposition of a higher marginal','Reconstruct each output in the finite difference and exchange sums. Dividends omitting a difference variable cancel, leaving those containing the entire target.'),
'cvpr2023-shapley':('Theorem 2: classical Shapley as equal dividend allocation','The original factorial-weighted marginal definition is converted into dividend allocation by the fully proved finite factorial convolution.'),
'cvpr2023-shapley-interaction':('Theorem 3: dividend weights for the Shapley interaction index','Apply the shared weighted higher-marginal identity to the original whole-target SII definition, including the empty target.'),
'cvpr2023-shapley-taylor':('Theorem 4: all order branches of the Shapley–Taylor index','The lower and higher branches follow from their definitions. The top-order branch follows from the finite factorial identity after checking all positive-order denominators.'),
'cvpr2023-scm-subset-sum':('SCM: binary AND triggers give a subset sum','A pattern fires exactly when every one of its variables is retained. Substituting that indicator into the finite linear readout gives the activated-pattern sum.'),
'cvpr2023-baseline-faithfulness':('Complete dividends remain exact after changing the input baseline','Recompute the masked game and every dividend for each baseline. Complete reconstruction has zero squared residual at every mask. A separate counterexample addresses the additional truncated-loss interpretation of the source sentence.'),
'cvpr2023-aog-regrouping':('AOG: equivalent regrouping of shared AND subpatterns','A parent pattern is the union of its children’s variable sets. The product of their binary triggers equals the parent trigger, so sharing and regrouping preserve the weighted root output.'),
'cvpr2023-addmul-coefficients':('Binary addition–multiplication models: dividends are activated-term coefficients','Coordinate masking at a zero input baseline turns each monomial into a pure AND response. Linearity then combines its exact dividend; the coefficient includes the original sample product.'),
'cvpr-inv-harsanyi-definition':('Original definition of the Harsanyi dividend','Source definition retained in the full inventory; it has no separate proof obligation.'),
'cvpr-inv-mask-definition':('Masks defined by a fixed input and input baseline','Source definition retained in the full inventory; the original input baseline is distinct from the scalar output baseline.'),
'cvpr-inv-remark1':('Empirical sparsity: a few patterns approximate the DNN','An empirical observation, kept separate from a universally proved sparsity theorem.'),
'cvpr-inv-combinatorial-beta':('Binomial identities and Beta-function properties','The source lists combinatorial auxiliary material. Its exact source-transcription status remains the status recorded in the Chinese input.'),
'cvpr-inv-optimization':('Pattern selection and the L0-to-L1 relaxation','An optimization formulation and relaxation, without a claim that the two optimization problems have identical minimizers.'),
'cvpr-inv-explained-ratio':('Ratio of explained interaction effects','A defined evaluation quantity, with its denominator convention to be read from the source.'),
'cvpr-inv-mdl':('MDL objective and greedy selection rules','Algorithmic source material; the inventory does not supply a theorem that the greedy rules achieve a global optimum.'),
'cvpr-inv-evaluation':('Experimental metrics, similarities and results','Empirical and evaluation source material, separate from formal proof targets.'),
'cvpr-inv-synthesized-labels':('Sigmoid and And–Or synthetic ground-truth rules','Synthetic label-generation rules used in experiments, rather than a general theorem about trained networks.'),
'cvpr-inv-runtime':('Runtime and dimension reduction','Reported computational methods and experimental runtime, without a new universal complexity guarantee.'),
'cvpr-inv-bow':('AOG versus bag of words and shared phrases','A source comparison and illustration, kept distinct from the exact AND regrouping identity.'),
'cvpr-inv-related-work':('Results cited from related literature','External claims remain marked as citations rather than local author proofs.')}
A={
'cvpr2023-symmetry':[r'$i,j\in N$; for every $U\subseteq N\setminus\{i,j\}$, $g(U\cup\{i\})=g(U\cup\{j\})$.'],
'cvpr2023-anonymity':[r'$\pi:N\to N$ is bijective; $g^\pi(V)=g(\pi^{-1}V)$.'],
'cvpr2023-recursive':[r'$i\in N$ and $S\subseteq N\setminus\{i\}$.'],
'cvpr2023-interaction-distribution':[r'$T\subseteq N$; $c\in\mathbb R$; the empty target is allowed.'],
'cvpr2023-marginal-decomposition':[r'$T,S\subseteq N$ and $T\cap S=\varnothing$; either set may be empty.'],
'cvpr2023-shapley':[r'$i\in N$; use the original classical factorial-weighted marginal definition.'],
'cvpr2023-shapley-interaction':[r'$T\subseteq N$; use the original factorial-weighted SII definition, including the empty target.'],
'cvpr2023-shapley-taylor':[r'$T\subseteq N$; use the original three-branch STI definition at a positive order $k>0$. The source does not explicitly state positivity; order zero is outside the present verified scope.'],
'cvpr2023-scm-subset-sum':[r'A finite pattern family and binary triggers; the input and its masking rule are fixed.'],
'cvpr2023-aog-regrouping':[r'Each parent pattern is the union of finitely many child variable sets. Triggers are containment indicators, and the original coefficients and linear root are retained. Children may be shared and their variables may overlap.'],
'cvpr2023-addmul-coefficients':['Binary coordinates and input baseline zero; merge polynomial terms with identical variable sets. A zero input baseline does not imply a zero output baseline for general models.']}
LOCAL={
'cvpr-recon-context':('Translate the original SCM into one fixed coefficient family',r'For a fixed input, model and baseline, $C_A(x_S)=1$ exactly when $A\subseteq S$. The theorem therefore concerns the same coefficients $w_A$ at every $S\subseteq N$. Statistical independence of input variables is not a premise of this finite algebra.'),
'cvpr-recon-main':('Exchange finite sums and cancel each interval',r'Expand $w_A$ at fixed $S$. Each pair $L\subseteq A\subseteq S$ occurs once, so exchange the finite sums. For fixed $L$, let $B=A\setminus L\subseteq S\setminus L$, a bijection with $|A|-|L|=|B|$. If $L\ne S$, choose a variable in the difference and pair subsets with and without it; opposite signs cancel. If $L=S$, only empty $B$ remains with coefficient 1. Thus only $g(S)$ survives.'),
'cvpr-recon-empty':('Check the empty mask and two variables',r'At an empty mask the only term is $w_\varnothing=b$. For mask outputs 7, 8, 9 and 13 on two variables, the dividends are 7, 1, 2 and 3; reconstruction gives full output 13, empty output 7 and singleton outputs 8 and 9.'),
'cvpr-unique-quantifiers':('Keep every mask and one fixed coefficient family',r'Assume fixed coefficients $d_A$ reconstruct $g(S)$ for every $S\subseteq N$, including the empty set. An equality only at the full input cannot imply uniqueness.'),
'cvpr-unique-induction':('Use strong induction on set cardinality',r'The empty set gives $d_\varnothing=g(\varnothing)=w_\varnothing$. The strong induction hypothesis says that every subset with cardinality below $|S|$ has its correct dividend. Every proper subset of $S$ is covered. Subtract the two reconstruction equalities at $S$ after replacing their identical proper-subset terms; the remaining terms give $d_S=w_S$. Since $S$ is arbitrary, all coefficients are unique.'),
'cvpr-unique-empty':('Check the empty coefficient and necessary quantifiers',r'For outputs 7, 8, 9 and 13, the empty equation fixes coefficient 7, the singleton equations fix 1 and 2, and the full equation fixes 3. If only the full output 13 is required, putting all of 13 at the empty coefficient or all at the full-set coefficient both fit that one equality. Other masks cannot be omitted.'),
'dummy-counterexample':('Give the full counterexample under the original quantifiers',r'Take $N=\{i\}$, $g(\varnothing)=0$ and $g(\{i\})=1$. The only environment is empty, so the premise is $1=0+1$. The conclusion requires a zero singleton dividend, but its actual value is $1-0=1$. The original proposition is false. No nonempty-environment assumption is added, and the library’s null-player theorem is not passed off as this additive Dummy statement.'),
'scm-trigger':('Check each binary trigger',r'For a retained set $S$, set $X_i=\mathbf1_{i\in S}$. If $A\subseteq S$, every factor in the pattern product is 1; otherwise some factor is zero. The product is therefore exactly the containment indicator. The empty product is 1, so the empty pattern always fires.'),
'scm-sum':('Retain exactly the activated patterns',r'Substitute the trigger identity into the SCM readout for any finite retained pattern family. Every pattern not contained in $S$ contributes zero, so only contained patterns remain. The family need not contain all patterns. When it is the full powerset, reconstruction identifies the sum with $g(S)$.'),
'base-rereconstruct':('Recompute all dividends for each input baseline',r'For each baseline $r$, define all masks and the game $g_r(S)=v(x_S^{(r)})$, then recompute its dividends. Finite reconstruction gives the exact output at every mask. A baseline change requires changing the game and recomputing the coefficients; they generally do change.'),
'base-unfaith':('Each complete squared residual is zero',r'Without deleting patterns, each residual between the masked output and its complete dividend sum vanishes. Squaring preserves zero, and the finite sum is zero. Any two baselines satisfy this statement separately. After truncation to a retained pattern family, the theorem no longer guarantees zero residual.'),
'base-truncated-counterexample':('Preserve the source sentence’s false truncated-loss interpretation',r'If the sentence that a baseline “just affects” the retained coefficients’ L1 norm is read as saying truncated loss is baseline-independent, it is false. For $v(z)=z$, original input 1, input baseline $r$, and only the empty pattern retained, the complete dividends are $r$ and $1-r$. The truncated loss is $(1-r)^2$ and changes with $r$. Complete-dividend loss remains zero. The complete-reconstruction subclaim is proved, while the additional interpretation is not counted as fully verified.'),
'aog-union':('Combine two child AND triggers',r'Containment of $A\cup B$ in $T$ is equivalent to containment of both $A$ and $B$. The union trigger is therefore the product of the two binary triggers. Overlap between the child variable sets is allowed because trigger values are zero or one.'),
'aog-tree':('Repeated merging preserves each pattern state and the root output',r'For a finite child family with variable sets $V_c$, the parent set is their union. Induct over the child family. The empty family gives an empty union and empty product, both with trigger 1. Inserting a child uses the two-set union identity and the induction hypothesis, proving the product identity. Child variables may overlap and a child may be shared by several parents. Applying such a grouping to every original pattern preserves each trigger; retaining its coefficient preserves the weighted root output.'),
'aog-empty':('Check an empty pattern and a shared-node example',r'A shared node with variable set $\{5,6\}$ groups the pattern $\{4,5,6\}$ into children $\{4\}$ and that node. With mask $\{4,5\}$ neither representation fires; with the full pattern mask both fire. The empty pattern and empty child product both have trigger 1. This proves equivalent regrouping only; optimality of the MDL greedy algorithm is separate.'),
'addmul-binary':('Evaluate each term at the fixed binary sample',r'For a monomial at input baseline zero, retaining its entire variable set keeps every factor; otherwise some factor is replaced by zero. Thus the masked monomial equals its coefficient times the original sample product times the containment indicator. An original zero factor makes that coefficient vanish; the empty monomial has product 1. Combine original terms with identical variable sets first.'),
'addmul-transform':('Transform each pure AND response and combine by linearity',r'The finite addition–multiplication polynomial, evaluated on actual coordinate masks, is a sum of pure AND games by the preceding identity. Each has a dividend only at its own variable set. Finite linearity therefore makes a fixed set receive precisely its original coefficient times its sample product, if present in the polynomial, and zero otherwise.'),
'addmul-examples':('Check both source samples and the boundary',r'The source model is $v(x)=3x_1-2x_2x_3-x_3x_4x_5+5x_4x_6$. At the all-ones sample its nonzero dividends are 3, −2, −1 and 5 at the four displayed monomial sets. When the third coordinate is zero, only dividends 3 and 5 remain. Full outputs are respectively 5 and 8. Both examples have zero empty-mask output and empty dividend; these are exact activated-term coefficients.')}
SIDE={}
for r in D['results']:
 if r.get('paper_id')!='cvpr2023-sparse-concepts':continue
 ident=r['id'];title,overview=INFO[ident]
 en=dict(title=title,overview=overview,assumptions=A.get(ident,['Finite universe; the same input, model and input baseline are fixed.'] if r.get('assumptions') else []),definitions=[dict(id=x['id'],body_md=COMMON) for x in r.get('definitions',[])],proof_scope=r.get('proof_scope',''),proof_steps=[])
 if len(en['assumptions'])!=len(r.get('assumptions',[])):
  # These three original domains each have one source assumption record.
  en['assumptions']=['The original conditions are those stated in the exact displayed source formula and in the complete shared proof below.']*len(r.get('assumptions',[]))
 if r.get('completion_scope'):en['completion_scope']=r['completion_scope']
 if ident.startswith('cvpr-inv-'):
  en['original_statement_md']='This entry is included in the complete inventory. Consult its formal source pages for the original material; an exact mathematical transcription has not yet been delivered in the existing input.'
  en['original_proof_md']='A complete mathematical transcription has not yet been delivered in the existing input. The formal PDF preserves the original source.'
 else:
  en['original_statement_note']='The formulas and quantifiers were checked against the formal PDF. The Chinese source text is a translation rather than a verbatim English quotation.'
  en['original_proof_note']='The author’s mathematical calculations and necessary argument are preserved, with printed errors retained. The formal PDF and page evidence preserve the original layout. Unnumbered arguments are distinguished from proofs not supplied by the authors.'
 for st in r.get('proof_steps',[]):
  if st['id']=='paper-notation-adaptation':
   en['proof_steps'].append(dict(id=st['id'],title='Match the paper definitions and apply the shared proof',body_md='The paper objects, quantifiers and baseline agree with the shared proposition below. The conditions above retain its application scope. The complete shared proof is presented continuously.',justification='The checked paper notation mapping is recorded in this result.'))
  else:
   title,body=LOCAL[st['id']]
   en['proof_steps'].append(dict(id=st['id'],title=title,body_md=body,justification='Direct evaluation at the two masks; no training or probability assumption is involved.' if st['id']=='base-truncated-counterexample' else ''))
 SIDE[ident]=en
out=ROOT/'corpus/public/translations/cvpr2023-sparse-concepts.en.json';out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(dict(schema_version=1,paper_id='cvpr2023-sparse-concepts',results=SIDE),ensure_ascii=False,indent=2)+'\n')
print('CVPR overlays',len(SIDE))
